const fs = require('node:fs'),
  path = require('node:path');
module.exports = function build(root) {
  const read = (name) =>
    fs.readFileSync(path.join(root, 'cloudfunctions/warmcare/lib', name), 'utf8');
  const wrap = (name, source) =>
    `const ${name} = (() => { const module = {exports:{}};\n${source}\nreturn module.exports;\n})();\n`;
  const source =
    '// Generated by npm run prepare:cloud. Edit lib/family.js or lib/entry.js.\n' +
    wrap('personalModule', read('personal.js')) +
    wrap(
      'familyModule',
      read('family.js').replace(/require\(['"]\.\/personal['"]\)/g, 'personalModule'),
    ) +
    read('entry.js').replace(/require\(['"]\.\/lib\/family['"]\)/g, 'familyModule');
  if (/require\(['"]\.\//.test(source))
    throw new Error('Unbundled local dependency in cloud entry');
  return source;
};
